"""Render metrics.json into a human-readable Markdown report."""

from __future__ import annotations

from pathlib import Path
from typing import Any


def _pct(x: float, digits: int = 1) -> str:
    return f"{100 * x:.{digits}f}%"


def _money(x: float) -> str:
    return f"{x:,.0f}"


def write_results_md(m: dict[str, Any], path: Path) -> Path:
    d, t, th = m["data"], m["test"], m["threshold"]
    ci = t["ci95"]
    lines: list[str] = [
        "# Results",
        "",
        "_Generated by `fraudlab train`; do not edit by hand._",
        "",
    ]

    lines += [
        "## Data",
        "",
        f"- {d['rows']:,} transactions after de-duplication, {d['frauds']:,} frauds "
        f"({_pct(d['fraud_rate'], 3)}).",
        f"- Development period: {d['dev_rows']:,} rows / {d['dev_frauds']} frauds. "
        f"Test period (last slice of time): {d['test_rows']:,} rows / {d['test_frauds']} frauds.",
        "",
        "## Cross-validation on the development period",
        "",
        "Expanding-window folds with a purge gap. Mean ± std over folds.",
        "",
        "| Model | Average precision | ROC-AUC | Recall @ alert budget | Fit time / fold (s) |",
        "|---|---|---|---|---|",
    ]
    for r in m["cv_summary"]:
        lines.append(
            f"| `{r['model']}` | {r['ap_mean']:.3f} ± {r['ap_std']:.3f} | {r['roc_auc_mean']:.3f} "
            f"| {_pct(r['recall_at_alert_rate_mean'])} | {r['fit_seconds_mean']:.1f} |"
        )

    tu = m["tuning"]
    lines += [
        "",
        f"Optuna ({tu['n_trials']} trials): best CV average precision {tu['best_cv_ap']:.3f}. "
        "This number is optimistically biased by the search; the held-out test below is the "
        "unbiased estimate.",
        "",
        "## Held-out test period (used once)",
        "",
        "| Model | Average precision | ROC-AUC |",
        "|---|---|---|",
        f"| **final (tuned LightGBM)** | **{t['average_precision']:.3f}** "
        f"(95% CI {ci['average_precision'][0]:.3f}–{ci['average_precision'][1]:.3f}) "
        f"| {t['roc_auc']:.3f} (95% CI {ci['roc_auc'][0]:.3f}–{ci['roc_auc'][1]:.3f}) |",
    ]
    for name, b in t["baselines"].items():
        lines.append(f"| {name} | {b['average_precision']:.3f} | {b['roc_auc']:.3f} |")
    lines.append(f"| random classifier | {t['prevalence']:.4f} | 0.500 |")

    lines += [
        "",
        "### Operating points",
        "",
        f"Assumptions: a missed fraud costs its transaction amount; reviewing one alert costs "
        f"{th['review_cost']:.2f}. Baseline = no model (all fraud slips through).",
        "",
        "| Threshold policy | Threshold | Alerts | Precision | Recall | Missed fraud | Review cost "
        "| Net savings vs no model |",
        "|---|---|---|---|---|---|---|---|",
    ]
    for name, o in t["operating_points"].items():
        lines.append(
            f"| `{name}` | {o['threshold']:.3f} | {o['alerts']} | {_pct(o['precision'])} "
            f"| {_pct(o['recall'])} | {_money(o['missed_fraud_amount'])} "
            f"| {_money(o['review_cost_total'])} | {_money(o['net_savings'])} "
            f"({_pct(o['net_savings_pct'])}) |"
        )
    lines += [
        "",
        f"For the chosen `cost_optimal` policy, the bootstrap 95% CI is: precision "
        f"{_pct(ci['precision'][0])}–{_pct(ci['precision'][1])}, recall "
        f"{_pct(ci['recall'][0])}–{_pct(ci['recall'][1])}, net savings "
        f"{_money(ci['net_savings'][0])}–{_money(ci['net_savings'][1])}.",
        "",
        "### If analysts can only review a fixed share of traffic",
        "",
        "| Alert budget | Alerts | Precision | Recall |",
        "|---|---|---|---|",
    ]
    for a in t["alert_budgets"]:
        lines.append(
            f"| top {_pct(a['alert_rate'], 2)} | {a['alerts']} | {_pct(a['precision'])} "
            f"| {_pct(a['recall'])} |"
        )

    lines += [
        "",
        "## Explainability (mean |SHAP|, top 10)",
        "",
        "| Feature | Mean abs SHAP |",
        "|---|---|",
    ]
    for feat, v in m["explain"]["top_features"].items():
        lines.append(f"| `{feat}` | {v:.3f} |")
    lines += [
        "",
        "## Drift (PSI, development vs test period, top 8)",
        "",
        "| Feature | PSI | Status |",
        "|---|---|---|",
    ]
    for r in m["drift"]:
        lines.append(f"| `{r['feature']}` | {r['psi']:.3f} | {r['status']} |")

    env = m["environment"]
    lines += [
        "",
        "## Reproducibility",
        "",
        f"Run time {m['runtime_seconds']:.0f} s. Environment: "
        + ", ".join(f"{k} {v}" for k, v in env.items())
        + (f". Data SHA-256: `{d['sha256']}`." if d.get("sha256") else "."),
        "",
    ]
    path.write_text("\n".join(lines), encoding="utf-8")
    return path
